<section id="campus-home" hidden>
<style>.briefing-hero{background:#edf1e3;border:1px solid #d4ddc8;padding:26px;border-radius:8px;margin-bottom:22px}.briefing-hero h2{font:32px Georgia,serif;margin:9px 0}.briefing-counts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin:20px 0}.briefing-counts article{background:#fff;border:1px solid var(--line);border-radius:7px;padding:20px}.briefing-counts strong{display:block;font:32px Georgia,serif;margin-bottom:8px}.briefing-grid{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,1fr);gap:20px}.briefing-project{padding:15px 0;border-bottom:1px solid var(--line)}.briefing-project h3{margin:0 0 8px;font:21px Georgia,serif}.briefing-project a{color:#315b43}.briefing-project progress{width:100%;height:6px;accent-color:#315b43}.briefing-status{padding:12px 0;border-bottom:1px solid var(--line)}@media(max-width:1000px){.briefing-grid{grid-template-columns:1fr}.briefing-counts{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.briefing-hero{padding:20px}.briefing-counts article{padding:15px}.briefing-hero h2{font-size:28px}}</style>
<div class="actions"><button class="button" id="briefing-refresh">Refresh current records</button><button class="button primary" id="briefing-ai">Summarize with Ask Everbranch</button><a class="button" id="briefing-pdf" href="#">Download one-page briefing</a></div><p class="caption" id="briefing-asof"></p><div id="briefing-body" aria-live="polite"></div>
</section>
